    <div class="detail-section-heading">
      <h2 id="party-heading">Funding by party</h2>
      <p>Grouped by recipients' latest recorded party.</p>
    </div>
    {#if slices.length === 0}<p class="empty-details">
        {details.entryCount === 0
          ? "No funding entries are stored for this funder."
          : "No known funding totals are available."}
      </p>{:else}
      <div class="funder-party-chart">
        <div class="funder-pie">
          <svg
            viewBox="0 0 200 200"
            role="img"
            aria-label="Funding by party. Positive totals determine the pie shares."
          >
            {#if slices.every((slice) => slice.share === 0)}<circle
                cx="100"
                cy="100"
                r="90"
                fill="#ece8e1"
              />{/if}
            {#each slices as slice, index}
              {#if slice.share > 0}
                <g
                  role="button"
                  tabindex="0"
                  aria-label={slice.party.partyName || "Party unavailable"}
                  aria-describedby={tooltip?.index === index
                    ? "party-tooltip"
                    : undefined}
                  onpointermove={(event) => {
                    if (
                      hoverDismissed &&
                      (event.movementX || event.movementY) &&
                      event.pointerType !== "touch"
                    ) {
                      hoverDismissed = false;
                      show(index, event.currentTarget);
                    }
                  }}
                  onpointerenter={(event) => {
                    if (event.pointerType !== "touch" && !hoverDismissed)
                      show(index, event.currentTarget);
                  }}
                  onmouseleave={dismiss}
                  onfocus={(event) => show(index, event.currentTarget)}
                  onblur={dismiss}
                  onpointerdown={(event) => {
                    if (event.pointerType === "touch") tap(index, event);
                  }}
                  onclick={(event) => {
                    if (
                      !(event instanceof PointerEvent) ||
                      event.pointerType !== "touch"
                    )
                      show(index, event.currentTarget);
                  }}
                  onkeydown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault();
                      show(index, event.currentTarget);
                    }
                  }}
                >
                  {#if slice.share === 1}<circle
                      cx="100"
                      cy="100"
                      r="90"
                      fill={slice.color}
                    />
                  {:else}<path d={slice.path} fill={slice.color} />{/if}
                </g>
              {/if}
            {/each}
          </svg>
          {#if slices.every((slice) => slice.share === 0)}<p
              class="coverage-note"
            >
              Pie unavailable. No positive known totals are recorded.
            </p>{:else if slices.some((slice) => slice.party.amount === null || slice.party.amount.startsWith("-"))}<p
              class="filter-context"
            >
              The pie shows positive known totals. Negative and unavailable
              totals are available from the party controls.
            </p>{/if}
        </div>
        <ul class="funder-party-legend">
          {#each slices as slice, index}<li>
              <button
                type="button"
                aria-describedby={tooltip?.index === index
                  ? "party-tooltip"
                  : undefined}
                onpointermove={(event) => {
                  if (
                    hoverDismissed &&
                    (event.movementX || event.movementY) &&
                    event.pointerType !== "touch"
                  ) {
                    hoverDismissed = false;
                    show(index, event.currentTarget);
                  }
                }}
                onpointerenter={(event) => {
                  if (event.pointerType !== "touch" && !hoverDismissed)
                    show(index, event.currentTarget);
                }}
                onmouseleave={dismiss}
                onfocus={(event) => show(index, event.currentTarget)}
                onblur={dismiss}
                onpointerdown={(event) => {
                  if (event.pointerType === "touch") tap(index, event);
                }}
                onclick={(event) => {
                  if (
                    !(event instanceof PointerEvent) ||
                    event.pointerType !== "touch"
                  )
                    show(index, event.currentTarget);
                }}
              >
                <span class="party-swatch" style:background={slice.color}
                ></span>
                <div>
                  <span>{slice.party.partyName || "Party unavailable"}</span
                  ><span class="entry-count"
                    >{slice.party.entryCount}
                    {slice.party.entryCount === 1
                      ? "entry"
                      : "entries"}{#if slice.party.unknownAmountCount > 0}, {slice
                        .party.unknownAmountCount}
                      {slice.party.unknownAmountCount === 1
                        ? "amount"
                        : "amounts"} unavailable{/if}</span
                  >
                </div>
              </button>
            </li>{/each}
        </ul>
      </div>
    {/if}
  </section>
  <RegistrationTimeline
    context="funding"
    months={timeline.months}
    undated={timeline.undated}
  />
</div>
{#if tooltip}{@const party = slices[tooltip.index].party}
  <div
    id="party-tooltip"
    class="party-tooltip"
    role="tooltip"
    style:left={`${tooltip.left}px`}
    style:top={`${tooltip.top}px`}
    onmouseenter={keepOpen}
    onmouseleave={dismiss}
  >
    <span>{party.partyName || "Party unavailable"}</span>
    <strong>{formatPounds(party.amount)}</strong>
  </div>
{/if}
<section aria-labelledby="recipients-heading">
  <div class="detail-section-heading">
    <h2 id="recipients-heading">Top 10 recipients</h2>
    <p>MPs ranked by known declared value.</p>
  </div>
  {#if !pounds?.topRecipients.length}<p class="empty-details">
      No recipients are available.
    </p>{:else}
    <div class="summary-columns funder-recipients">
      <table>
        <caption class="visually-hidden"
          >Top recipients of declared funding</caption
        ><thead
          ><tr><th scope="col">MP</th><th scope="col">Known total</th></tr
          ></thead
        ><tbody>
          {#each pounds.topRecipients as recipient}<tr
              ><th scope="row"
                ><a href={memberHref(recipient.member.id, "summary")}
                  >{recipient.member.name}</a
                ><span class="entry-count"
                  >{recipient.member.partyName || "Party unavailable"}</span
                ></th
              ><td
                ><span class="amount">{formatPounds(recipient.amount)}</span
                >{#if recipient.unknownAmountCount > 0}<span
                    class="partial-note"
                    >{recipient.unknownAmountCount}
                    {recipient.unknownAmountCount === 1 ? "amount" : "amounts"} unavailable</span
                  >{/if}</td
              ></tr
            >{/each}
        </tbody>
      </table>
    </div>
  {/if}
</section>
{#if details.funder.aliases.length > 0}<details
    class="recorded-names funder-recorded-names"
    role="region"
    aria-label="Recorded names"
  >
    <summary>Recorded names</summary>
    <ul>
      {#each details.funder.aliases as alias}<li>{alias}</li>{/each}
    </ul>
  </details>{/if}
<script lang="ts">
  import { categoryBars } from "./lib/entity-details";
  import { formatPounds } from "./lib/member-summary";
  import type { RegistrationMonth } from "./lib/registration-timeline";
  let {
    months,
    undated,
    context,
  }: {
    months: RegistrationMonth[];
    undated: boolean;
    context: "earnings" | "funding";
  } = $props();
  const copy = $derived(
    {
      earnings: {
        heading: "Earnings by registration month",
        title: "Monthly registered earnings",
        missing: "Registration dates are unavailable for earnings.",
        empty: "No registered earnings available.",
        undated: "Earnings without registration dates are excluded.",
      },
      funding: {
        heading: "Funding by registration month",
        title: "Monthly registered funding",
        missing: "Registration dates are unavailable for funding.",
        empty: "No registered funding available.",
        undated: "Funding without registration dates is excluded.",
      },
    }[context],
  );
  const bars = $derived(categoryBars(months, "maximum"));
  const positive = $derived(
    Math.max(0, ...bars.filter((bar) => !bar.negative).map((bar) => bar.width)),
  );
  const negative = $derived(
    Math.max(0, ...bars.filter((bar) => bar.negative).map((bar) => bar.width)),
  );
  const extent = $derived(positive + negative || 100);
  const baseline = $derived(4 + (positive / extent) * 314);
  const minimum = $derived(
    months[bars.findIndex((bar) => bar.negative && bar.width === negative)]
      ?.amount ?? "0",
  );
  function tick(index: number): boolean {
    return (
      index === 0 ||
      index === months.length - 1 ||
      (months.length > 10 &&
        index % Math.ceil(months.length / 4) === 0 &&
        months.length - 1 - index >= Math.ceil(months.length / 4))
    );
  }
  function monthLabel(start: string): string {
    return new Intl.DateTimeFormat("en-GB", {
      month: "short",
      year: "numeric",
      timeZone: "UTC",
    }).format(new Date(start));
  }
</script>

<section class="member-earnings" aria-labelledby={`${context}-heading`}>
  <h2 id={`${context}-heading`}>{copy.heading}</h2>
  {#if months.length}
    <svg
      class="earnings-chart"
      viewBox="0 0 560 360"
      role="img"
      aria-labelledby={`${context}-title ${context}-description`}
    >
      <title id={`${context}-title`}>{copy.title}</title><desc
        id={`${context}-description`}
        >Known amounts by UTC registration month. Each bar shows its exact
        amount in its tooltip.</desc
      >
      <line
        x1="0"
        x2="560"
        y1={baseline}
        y2={baseline}
        class="chart-baseline"
      />
      {#each months as month, index}{@const bar = bars[index]}{@const height =
          (bar.width / extent) * 314}
        <rect
          x={(index * 560) / months.length + 1}
          y={bar.negative ? baseline : baseline - height}
          width={Math.max(1, 560 / months.length - 2)}
          {height}
          class="earnings-bar"
          class:negative={bar.negative}
          ><title
            >{monthLabel(month.start)}: {formatPounds(
              month.amount,
            )}{month.incomplete ? " (some amounts unavailable)" : ""}</title
          ></rect
        >
        {#if tick(index)}<text
            x={(index * 540) / Math.max(1, months.length - 1) + 10}
            y="354"
            text-anchor={index === 0
              ? "start"
              : index === months.length - 1
                ? "end"
                : "middle"}
            class="chart-axis">{monthLabel(month.start)}</text
          >{/if}{/each}
      <text
        x="0"
        y={negative ? 335 : Math.min(335, baseline + 16)}
        class="chart-axis">{negative ? formatPounds(minimum) : "£0"}</text
      >
    </svg>
    {#if months.some((month) => month.incomplete)}<p class="partial-note">
        Some monthly amounts are unavailable.
      </p>{/if}
  {:else}<p class="empty-details">
      {undated ? copy.missing : copy.empty}
    </p>{/if}
  {#if undated && months.length}<p class="partial-note">
      {copy.undated}
    </p>{/if}
</section>
